-- Reconstruction of KPI nodes n01..n05, not generated by an Atlas bridge.
-- Fiscal bounds are explicit fixture data, keyed by entity; no inferred calendar.
CREATE VIEW main.atlas_revenu_net AS
SELECT p.mois_fiscal, f.entite,
       SUM(f.montant_ttc - f.montant_taxes - f.avoirs) AS revenu_net
FROM main.fact_facturation AS f
JOIN main.periodes_fiscales AS p
  ON f.entite = p.entite
 AND f.date_facture >= p.date_debut
 AND f.date_facture < p.date_fin
WHERE f.statut = 'validée'
GROUP BY p.mois_fiscal, f.entite;
